  "welcome.noTrialNote": "આ સ્ક્રીન ખોલવાથી કંઈ શરૂ થતું નથી. કોઈ ટ્રાયલ શરૂ થતી નથી અને કોઈ કાર્ડ ચાર્જ થતું નથી — સાત દિવસની ટ્રાયલ ત્યારે જ શરૂ થાય છે જ્યારે તમે પ્લાન પસંદ કરીને તેની પુષ્ટિ કરો. બંને વેબસાઇટ પ્લાનમાં મોબાઇલ સાથી સામેલ છે, તેથી તમે તેના પર ક્યારેય વધારાની માસિક મોબાઇલ ફી ચૂકવતા નથી.",
