  "subscribe.invalidBody": "તમે અનુસરેલી લિંક અમે આપતા કોઈ પ્લાનનું નામ આપતી નથી. ચાલુ રાખવા નીચેથી એક પસંદ કરો — કંઈ સબસ્ક્રાઇબ થયું નથી.",
