  "subscribe.stripeNote": "ચેકઆઉટ Stripe દ્વારા સુરક્ષિત રીતે સંભાળાય છે. કોઈ ચાર્જ મંજૂર કરતા પહેલા તમને ચોક્કસ કુલ રકમ દેખાશે.",
