  "plans.backToWelcome": "સ્વાગત પેજ પર પાછા જાઓ",
  "plans.eyebrow": "પ્લાન અને સુવિધાઓ",
  "plans.title": "StockHaven પ્લાન સરખાવો",
  "plans.intro": "તમે ગમે તે પ્લાન પસંદ કરો, એક એકાઉન્ટ — Business પાંચ વ્યવસાય સુધી આવરી લે છે. કિંમતો US ડોલરમાં માસિક છે, અને પાત્ર નવા વેબસાઇટ ગ્રાહકોને Essentials અને Business બંનેમાં એક સાત-દિવસની ટ્રાયલ મળી શકે છે. હાલના Essentials સબસ્ક્રિપ્શનને Business માં અપગ્રેડ કરવાથી ટ્રાયલ ફરી શરૂ થતી નથી કે બીજી મફત ટ્રાયલ બનતી નથી. વેબસાઇટ પ્લાનની કિંમતો લાગુ પડતા કર પહેલાંની છે, જો કોઈ હોય તો. સબસ્ક્રિપ્શનને અધિકૃત કરતા પહેલા તમારો ચોક્કસ ચાર્જ બતાવવામાં આવશે.",
  "plans.availableAtLaunch": "મોબાઇલ લોન્ચ સમયે ઉપલબ્ધ",
