  "upgrade.eyebrow": "પ્લાન",
  "upgrade.title": "તમારી દુકાનને શું બંધબેસે તે પસંદ કરો",
  "upgrade.pendingCheckoutIntro": "તમે સબસ્ક્રિપ્શન પસંદ કરો ત્યાં સુધી આ નવું વર્કસ્પેસ Essentials સુધી મર્યાદિત છે. પાત્ર નવા ગ્રાહકોને એકાઉન્ટ દીઠ એક {days}-દિવસની ટ્રાયલ મળી શકે છે.",
  "upgrade.intro": "પાત્ર નવા ગ્રાહકોને એકાઉન્ટ દીઠ એક {days}-દિવસની ટ્રાયલ મળી શકે છે, પ્લાન દીઠ એક ટ્રાયલ નહીં. Essentials થી Business માં બદલવાથી ક્યારેય બીજી મફત ટ્રાયલ શરૂ થતી નથી. તમે છો",
  "upgrade.introGrandfathered": " — સંપૂર્ણ Business વર્કસ્પેસ, કોઈ ચાર્જ વિના.",
  "upgrade.introTrial": " (ટ્રાયલ).",
  "upgrade.introPeriod": ".",
  "upgrade.pastDueTitle": "પેમેન્ટ બાકી",
  "upgrade.pastDueBody": "તમારું છેલ્લું પેમેન્ટ થયું નથી, તેથી આ સબસ્ક્રિપ્શન બાકી છે. નીચે તમારી પેમેન્ટ પદ્ધતિ અપડેટ કરો — Stripe તેના પોતાના સમયપત્રક પર ફરી પ્રયાસ કરશે, અને તમારું સબસ્ક્રિપ્શન વહેલું રદ થશે નહીં. જો મદદ જોઈએ તો ઈમેઈલ કરો",
  "upgrade.updatePaymentMethod": "પેમેન્ટ પદ્ધતિ અપડેટ કરો",
