  "upgrade.previewFirstCharge": "નવી કિંમતે પહેલો ચાર્જ",
  "upgrade.previewTrialEnds": "ટ્રાયલ પૂરી થાય છે (બદલાયેલ નથી)",
  "upgrade.previewToValue": "{name} — {price}/માસ",
  "upgrade.previewUpgradeNote": "અપગ્રેડ કરવાથી ક્યારેય તમારી મફત ટ્રાયલ ફરી શરૂ થતી નથી, અને તે ક્યારેય બીજું સબસ્ક્રિપ્શન બનાવતું નથી.",
  "upgrade.previewDowngradeNote": "ડાઉનગ્રેડ તમારા ચૂકવેલા સમયગાળાના અંતે અસરકારક થાય છે. તમારો ગુમાવેલી-સુવિધાનો ડેટા રાખવામાં આવે છે પણ અપ્રાપ્ય બને છે — ડાઉનગ્રેડની આડઅસર તરીકે તે ક્યારેય કાઢી નખાતો નથી.",
