  "billing.cancel.refundsRest": "રદ કરવાથી જાતે રિફંડ મળતો નથી. પહેલા પેમેન્ટનો રિફંડ ફક્ત ત્યારે જ લાગુ પડે છે જો તમે પહેલા સફળ ચૂકવેલા ચાર્જના 3 દિવસ (72 કલાક)માં રદ કરો, {contact} દ્વારા વિનંતી કરેલો.",
