  "billing.cancelError.subscriptionPaidThroughUnverified": "અમે તમારી ચૂકવેલી-તારીખની પુષ્ટિ કરી શક્યા નહીં. કંઈ બદલાયું નથી — કૃપા કરીને ફરી પ્રયાસ કરો, કે સપોર્ટનો સંપર્ક કરો.",
