  "exports.eyebrow": "ડેટા",
  "exports.title": "એક્સપોર્ટ અને બેકઅપ",
  "exports.subtitleStart": "ડાઉનલોડ હંમેશા મર્યાદિત હોય છે",
  "exports.subtitleRest": ". દરેક ફાઇલ પર વ્યવસાયનું નામ અને તે બનાવ્યાની તારીખ લખેલી હોય છે.",
  "exports.createBusinessFirst": "પહેલા વ્યવસાય બનાવો — એક્સપોર્ટ વ્યવસાયના હોય છે, એપના નહીં.",
  "exports.lockedTitle": "CSV અને Excel એક્સપોર્ટ Business સુવિધા છે",
  "exports.lockedDesc": "તમારું વર્કસ્પેસ Essentials પ્લાન પર છે. Business CSV અને Excel એક્સપોર્ટ, સ્ટોક મૂલ્યાંકન, અમર્યાદિત પ્રોડક્ટ અને સ્ટાફ, સપ્લાયર, ખરીદી અને બંડલ ઉમેરે છે.",
  "exports.seeBusiness": "Business માં શું સામેલ છે તે જુઓ",
  "exports.whatTheseAre": "આ ફાઇલ શું છે",
  "exports.about1": "દરેક ડેટાસેટ CSV કે વાસ્તવિક Excel વર્કબુક (.xlsx) તરીકે આવે છે — સંપૂર્ણ ઇન્વેન્ટરી વર્કબુક ફક્ત Excel છે, દરેક ડેટાસેટ દીઠ એક શીટ સાથે. CSV ફાઇલ Excel, Numbers, Google Sheets અને મોટાભાગની સ્ટોક એપમાં ખુલે છે. UTF-8 ટેક્સ્ટ, અવતરણચિહ્નવાળા અલ્પવિરામ, નોંધમાં લાઇન બ્રેક અને કોડમાં આગળના શૂન્ય બધા જળવાય છે, અને સૂત્ર જેવા શરૂ થતા સેલ નિષ્ક્રિય કરાય છે જેથી સ્પ્રેડશીટ તેમને ટેક્સ્ટ તરીકે ખોલે.",
  "exports.about2": "Excel ફાઇલમાં, SKU, UPC, ISBN અને બારકોડ ટેક્સ્ટ સેલ છે — ક્યારેય વૈજ્ઞાનિક નોટેશન નહીં અને ક્યારેય કાપેલા શૂન્ય નહીં — કોલમ પહોળાઈ, હેડર ફિલ્ટર અને ચલણ કે માત્રા ફોર્મેટ લાગુ કરેલા સાથે. સંપૂર્ણ ઇન્વેન્ટરી વર્કબુક પ્રોડક્ટ, સ્ટોક સ્તર, લોકેશન અને હલનચલનને અલગ શીટ પર રાખે છે.",
  "exports.about3": "ખૂબ મોટા એક્સપોર્ટ ડેટાસેટ દીઠ 20,000 પંક્તિ પર અટકે છે — જ્યારે તે થાય ત્યારે ફાઇલના નામમાં તે કહેવાય છે (truncated-20000), જેથી આંશિક ફાઇલ ક્યારેય સંપૂર્ણ તરીકે પસાર ન થાય.",
  "exports.about4": "બેકઅપ તમારા ડેટાનો સ્નેપશોટ છે, એક-ક્લિક રિસ્ટોર નહીં. તેને પુનઃસ્થાપિત કરવું મેન્યુઅલ, સમીક્ષા-પહેલાનું કામ છે, તેથી ફાઇલ સુરક્ષિત રાખો — એપમાં કંઈ તેનાથી કાઢી નાખેલો વ્યવસાય ફરી બનાવી શકતું નથી. એપ કોડ અને Base44 પ્લેટફોર્મ બેકઅપ આ ફાઇલોથી અલગ સંભાળાય છે.",
  "exports.about5": "ફોટા અને જોડાણ તેમની સંગ્રહિત લિંક તરીકે સૂચિબદ્ધ થાય છે — છબી ફાઇલ પોતે ડાઉનલોડમાં પેક થતી નથી.",
  "exports.backupTitle": "સંપૂર્ણ બેકઅપ",
  "exports.backupDesc": "આ વ્યવસાયની પ્રોડક્ટ, લોકેશન, સ્ટોક સ્તર, સંપૂર્ણ હલનચલન લેજર, સપ્લાયર, ખરીદી, ઓર્ડર, રિટર્ન, ગણતરી અને લિસ્ટિંગ સાથેની એક ફાઇલ — વત્તા તેની પ્રોફાઇલ સેટિંગ્સ. તેને ક્યાંક તમે નિયંત્રણ કરો ત્યાં રાખો.",
  "exports.backupIncludes1": "પ્રોડક્ટ, કોડ, કિંમત અને નોંધ",
