  "settings.billing.unavailableDetail": "આ વ્યવસાય માટે અમે વર્તમાન Stripe સબસ્ક્રિપ્શન ચકાસી શક્યા નહીં. આનો અર્થ એ નથી કે તમારું સબસ્ક્રિપ્શન રદ થયું છે, નિષ્ક્રિય છે, કે ભવિષ્યના ચાર્જથી મુક્ત છે.",
