  "settings.businesses.taglinePlaceholder": "ટૂંકું વર્ણન",
  "settings.businesses.title": "તમારા વ્યવસાય",
  "settings.businesses.tryAgain": "ફરી પ્રયાસ કરો",
  "settings.cancelSubscription": "સબસ્ક્રિપ્શન રદ કરો",
  "settings.cancelTerms.appleLink": "Apple રદ કરવાની સૂચનાઓ",
  "settings.cancelTerms.googlePlayLink": "Google Play રદ કરવાની સૂચનાઓ",
  "settings.cancelTerms.graceTitle": "તમારા ચૂકવેલા સમયગાળા પછી — 15-દિવસની ગ્રેસ, પછી કાઢી નાખવું:",
  "settings.cancelTerms.intro": "આ ચૂકવેલા Luminous StockHaven સબસ્ક્રિપ્શન માટેની શરતો છે. વેબસાઇટ સબસ્ક્રિપ્શન બિલિંગ Stripe દ્વારા છે. તમે નીચેના Cancel Subscription બટનથી કોઈપણ સમયે જાતે તમારું સબસ્ક્રિપ્શન રદ કરી શકો છો — કોઈ સ્ટાફ મંજૂરી જરૂરી નથી. રદ અને રિફંડ વિનંતીઓ સત્તાવાર ગ્રાહક સપોર્ટ સંપર્ક, theluminousbookshop@outlook.com દ્વારા પણ સંભાળી શકાય છે.",
  "settings.cancelTerms.noApprovalBody": "તમે કોઈપણ સમયે જાતે તમારું સબસ્ક્રિપ્શન રદ કરી શકો છો. કોઈ સ્ટાફ મંજૂરી જરૂરી નથી. ભવિષ્યના રિન્યુઅલ ફક્ત બિલિંગ પ્રોવાઇડર રદ કરવાની પુષ્ટિ કરે પછી જ બંધ થાય છે.",
  "settings.cancelTerms.noApprovalTitle": "મંજૂરી વિના રદ કરો:",
  "settings.cancelTerms.paymentBody": "ચૂકવેલી ટ્રાયલ માટે, સાત-દિવસની ટ્રાયલ માટે સાઇનઅપ સમયે પેમેન્ટ પદ્ધતિ જરૂરી છે. લાગુ ટ્રાયલ રદ કરવાની સમયમર્યાદામાં રદ ન થાય તો, પસંદ કરેલો માસિક પ્લાન ટ્રાયલ પછી આપોઆપ ચાર્જ થશે. કિંમત, પહેલી બિલિંગ તારીખ અને પ્રોવાઇડર-વિશિષ્ટ રદ કરવાની સમયમર્યાદા સાઇનઅપ દરમિયાન બતાવવી જ જોઈએ. ટ્રાયલ બિલિંગ Stripe દ્વારા છે.",
  "settings.cancelTerms.paymentTitle": "પેમેન્ટ પદ્ધતિ અને ઓટોમેટિક રિન્યુઅલ:",
  "settings.cancelTerms.remainingBody": "જો તમે બિલિંગ સમયગાળા માટે પહેલેથી ચૂકવણી કરી હોય, તો તમે તે ચકાસાયેલી ચૂકવેલી-તારીખ સુધી પ્રવેશ રાખી શકો છો. વહેલી સમાપ્તિ માટે યોગ્ય પ્રોવાઇડર પુષ્ટિ અને કોઈપણ લાગુ રિફંડ સંભાળ જરૂરી છે. મફત-ટ્રાયલ પ્રવેશ પ્રોવાઇડર-પુષ્ટિ ટ્રાયલ સમાપ્તિ તારીખ મુજબ સમાપ્ત થાય છે.",
  "settings.cancelTerms.remainingTitle": "બાકીનો પ્રવેશ:",
  "settings.cancelTerms.storesBody": "જો તમે ક્યારેય Google Play કે Apple App Store દ્વારા સબસ્ક્રાઇબ કરો, તો તમારું સબસ્ક્રિપ્શન તે સ્ટોર દ્વારા બિલ અને મેનેજ થાય છે. તમારે તેને સબસ્ક્રાઇબ કરવા વપરાયેલા તે જ Google કે Apple એકાઉન્ટના સબસ્ક્રિપ્શન વિભાગમાં સીધું રદ કરવું પડી શકે છે. અલગ વેબસાઇટ સબસ્ક્રિપ્શન રદ કરવાથી, આ એપ અનઇન્સ્ટોલ કરવાથી, કે Luminous StockHaven એકાઉન્ટ કાઢી નાખવાની વિનંતી કરવાથી સ્ટોર-બિલ સબસ્ક્રિપ્શન આપોઆપ રદ થતું નથી. કોણ તમને બિલ કરે છે તેની પુષ્ટિ કરવા તમારી ખરીદી રસીદ તપાસો.",
  "settings.cancelTerms.storesTitle": "Google Play અને Apple App Store સબસ્ક્રિપ્શન (જો તમે ક્યારેય સ્ટોર દ્વારા સબસ્ક્રાઇબ કરો):",
  "settings.cancelTerms.title": "રદ કરવાની શરતો અને નિયમો",
  "settings.cancelTerms.trialBody": "સાત-દિવસની ટ્રાયલ પાત્ર ગ્રાહક દીઠ ફક્ત એક વાર જ વાપરી શકાય છે. ટ્રાયલ કે સબસ્ક્રિપ્શન રદ કરવાથી બીજી ટ્રાયલ મળતી નથી; પરત આવતા ગ્રાહકોએ ચૂકવેલું સબસ્ક્રિપ્શન પસંદ કરવું પડશે.",
  "settings.cancelTerms.trialTitle": "એક મફત ટ્રાયલ:",
  "settings.canceled.endsOn": "આ સબસ્ક્રિપ્શન રદ થયું છે અને {date} ના રોજ સમાપ્ત થાય છે. ત્યાં સુધી તમને સંપૂર્ણ પ્રવેશ મળે છે.",
  "settings.delete.checking": "હાલની કાઢી નાખવાની વિનંતી તપાસી રહ્યા છીએ…",
  "settings.delete.description": "તમારું Luminous StockHaven સાઇન-ઇન એકાઉન્ટ દૂર કરવાની વિનંતી કરો.",
  "settings.delete.dialogDescription": "આ એકાઉન્ટ કાઢી નાખવાની સમીક્ષાની વિનંતી કરે છે. તે તમારું લોગિન કે ઇન્વેન્ટરી તરત દૂર કરતું નથી, અને તે કોઈ Stripe સબસ્ક્રિપ્શન રદ કરતું નથી. વિનંતી સબમિટ કરવાની પુષ્ટિ કરવા {word} ટાઇપ કરો.",
  "settings.delete.dialogTitle": "એકાઉન્ટ કાઢી નાખવાની વિનંતી કરો",
  "settings.delete.enterDelete": "પુષ્ટિ કરવા {word} લખો",
  "settings.delete.exportFirst": "જો તમારે તમારા રેકોર્ડ રાખવા હોય તો પહેલા તમારી ઇન્વેન્ટરી એક્સપોર્ટ કરો.",
