  "settings.switcher.newDescription": "દરેક વ્યવસાય તેની પોતાની પ્રોડક્ટ, લોકેશન, સપ્લાયર અને ખરીદી ઓર્ડર રાખે છે. તેમની વચ્ચે કંઈ શેર થતું નથી.",
