  "workforce.inbox.help": "તમારી ટીમ માટે ક્લોક ઘટનાઓ, રજાના જવાબ, કાર્યો, પગાર સ્ટબ અને શેડ્યૂલ ફેરફાર, સૌથી નવું પહેલા.",
