  "workforce.messages.emptyThread": "હજી કોઈ સંદેશ નથી. શરૂઆત કરવા માટે નમસ્તે કહો.",
  "workforce.messages.help": "તમારી ટીમ સાથે ખાનગી એક-થી-એક સંદેશ — બીજી કોઈ એપની જરૂર નથી. વાતચીતમાં ફક્ત બે વ્યક્તિ જ તે વાંચી શકે છે, ઉપરાંત વ્યવસાય માલિક, જે તેમના સ્ટોરની દેખરેખ રાખે છે.",
