  "training.track.managerHelp": "ટીમને રોજ ચલાવવા માટે: શેડ્યૂલ, રજા, કાર્યો, પગાર સ્ટબ અને તમારા સ્ટાફને તાલીમ.",
  "training.track.owner": "માલિક ટ્રેક",
  "training.track.ownerHelp": "એપમાં બધું, પેરોલ, બિલિંગ અને ફક્ત માલિક સ્પર્શી શકે તેવા ભાગો સહિત.",
  "training.track.staff": "સ્ટાફ ટ્રેક",
