  "training.warningSentOn": "ચેતવણી મોકલાઈ {date}",
  "auth.sameEmailNotice": "પહેલેથી Google Play કે App Store માંથી અમારી એપ છે? અહીં એ જ ઈમેઈલ વાપરો — જેનાથી તમે એપમાં સાઇન ઇન કરો છો — જેથી તમારો સ્ટોર અને તમારી ઇન્વેન્ટરી તમારી સાથે આવે. અલગ ઈમેઈલ તદ્દન નવો, ખાલી સ્ટોરફ્રન્ટ શરૂ કરે છે.",
