  "recovery.title": "તમારું એકાઉન્ટ પુનઃપ્રાપ્ત કરો",
  "recovery.subtitle": "તમારું એકાઉન્ટ જે ઈમેઈલ હેઠળ છે તેની ઍક્સેસ ખોવાઈ ગઈ? તમારી ફાજલ ચાવીઓ તમને તમારા સ્ટોર પર પાછા લઈ જઈ શકે છે.",
