  "recovery.backupCodeHint": "તમે Settings → Security માંથી સાચવેલા એક-વારના કોડ. દરેક કોડ બરાબર એક વાર કામ કરે છે.",
  "recovery.useBackupCode": "મારો બેકઅપ કોડ વાપરો",
