  "rewards.give.help": "પુરસ્કાર એક ટીમ સભ્ય પાસે જાય છે. મેનેજર સ્ટાફને પુરસ્કાર આપે છે; માલિક ટીમમાં કોઈને પણ પુરસ્કાર આપી શકે છે.",
