  "rewards.subtitle": "પુરસ્કારથી આભાર કહો — ટકા છૂટ, ગિફ્ટ કાર્ડ, કે તમે વર્ણવો તે કંઈપણ.",
  "rewards.title": "પુરસ્કાર અને પ્રોત્સાહન",
