  "rewards.voided": "પુરસ્કાર રદ થયો.",
  "workforce.tab.rewards": "પુરસ્કાર",
  "training.lessons.mgr-give-rewards.step1": "Workforce ખોલો અને Rewards પર ટેપ કરો. ટીમ સભ્ય પસંદ કરો, પછી પ્રકાર: સ્ટોરમાં ટકા છૂટ, ગિફ્ટ કાર્ડ, કે બીજું કંઈક જે તમે તમારા પોતાના શબ્દોમાં વર્ણવો.",
  "training.lessons.mgr-give-rewards.step2": "પુરસ્કારને ટૂંકું નામ આપો અને જો તમને ગમે તો નોંધ. વ્યક્તિને તરત ઘંટડી મળે છે, અને પુરસ્કાર તેમના My rewards માં તેના પોતાના કોડ સાથે રાહ જુએ છે.",
  "training.lessons.mgr-give-rewards.step3": "સીમા, ડિઝાઇન પ્રમાણે: તમે ફક્ત STAFF ને પુરસ્કાર આપો છો. તમે તમારી જાતને કે બીજા મેનેજરને પુરસ્કાર આપી શકતા નથી — મેનેજરને પુરસ્કાર આપવો એ માલિકનો નિર્ણય છે, અને એપ તેને સ્પષ્ટપણે નકારશે.",
  "training.lessons.mgr-give-rewards.step4": "ટિલ પર, ટીમ સભ્ય તમને બતાવે છે તે કોડ ટાઇપ કરો અને તેને વપરાયેલો ચિહ્નિત કરો — દરેક કોડ એક વાર કામ કરે છે. જો યોજના બદલાય તો તમે આપેલો પુરસ્કાર તમે રદ કરી શકો છો; માલિકની ભેટ રદ કરવાની માલિકની છે.",
  "training.lessons.mgr-give-rewards.title": "તમારા સ્ટાફને પુરસ્કાર આપવા",
  "training.lessons.owner-give-rewards.step1": "પુરસ્કાર Workforce માં, Rewards ટેબ પર રહે છે, અને તે ફક્ત Business-પ્લાન છે — Essentials પર ટેબ લૉક કરેલો દરવાજો બતાવે છે, જેથી તમારી ટીમ જોઈ શકે કે મોટો પ્લાન શું ધરાવે છે.",
  "training.lessons.owner-give-rewards.step2": "તમે ટીમમાં કોઈને પણ પુરસ્કાર આપી શકો છો — સ્ટાફ અને મેનેજર બંનેને. વ્યક્તિ પસંદ કરો, પછી પ્રકાર: સ્ટોરમાં ટકા છૂટ (તમે પસંદ કરો તે કોઈપણ ટકા), ગમે ત્યાંનું ગિફ્ટ કાર્ડ, કે તમે તમારા પોતાના શબ્દોમાં વર્ણવો તે કોઈપણ પ્રોત્સાહન.",
  "training.lessons.owner-give-rewards.step3": "પુરસ્કાર તેના પોતાના એક-વારના કોડ સાથે આવે છે અને વ્યક્તિની ઘંટડી વગાડે છે. તેઓ ટિલ પર કોડ બતાવે છે; માલિક કે મેનેજર તેને વપરાયેલો ચિહ્નિત કરવા માટે ટાઇપ કરે છે.",
  "training.lessons.owner-give-rewards.step4": "છાપેલી કે શેર કરેલી પુરસ્કાર સ્લિપ પર ફક્ત તમારા વ્યવસાયનું નામ હોય છે — ક્યારેય એપનું નહીં. તે તમારા સ્ટોરનો આભાર છે, જાહેરાત નહીં.",
  "training.lessons.owner-give-rewards.title": "પુરસ્કાર આપવા (Business પ્લાન)",
  "training.lessons.owner-rewards-oversight.step1": "તમારા મેનેજર પણ પુરસ્કાર આપી શકે છે — ફક્ત સ્ટાફને. એપ મેનેજર પોતાને કે બીજા મેનેજરને પુરસ્કાર આપે તે નકારે છે; મેનેજરને પુરસ્કાર આપવો હંમેશા તમારો નિર્ણય છે.",
  "training.lessons.owner-rewards-oversight.step2": "તમે Rewards history માં વ્યવસાયનો દરેક પુરસ્કાર જુઓ છો: કોણે આપ્યો, કોને મળ્યો, અને તે તૈયાર છે, વપરાયો છે કે રદ છે. મેનેજર ફક્ત તેમણે આપેલા અને તેમને મળેલા પુરસ્કાર જ જુએ છે.",
  "training.lessons.owner-rewards-oversight.step3": "તમે કોઈપણ પુરસ્કાર રદ કરી શકો છો, તમારા મેનેજરે આપેલો પણ. મેનેજર તેમની પોતાની ભેટ રદ કરી શકે છે, પણ તમારી ક્યારેય નહીં.",
  "training.lessons.owner-rewards-oversight.step4": "દરેક કોડ બરાબર એક વાર કામ કરે છે, અને રદ થયેલો પુરસ્કાર ક્યારેય વાપરી શકાતો નથી — ઇતિહાસ હંમેશા બતાવે છે કે પુરસ્કાર કઈ રીતે પૂરો થયો.",
  "training.lessons.owner-rewards-oversight.title": "પુરસ્કારની દેખરેખ: તમારા મેનેજરનું આપવું",
  "training.lessons.staff-your-rewards.step1": "જ્યારે તમારા મેનેજર કે માલિક તમને પુરસ્કાર આપે છે, ત્યારે તમારી ઘંટડી વાગે છે. Workforce ખોલો અને તેને My rewards હેઠળ જોવા માટે Rewards પર ટેપ કરો.",
  "training.lessons.staff-your-rewards.step2": "દરેક પુરસ્કારનો પોતાનો કોડ હોય છે. તે તમારી પાસે રાખો — જે ટિલ પર કોડ બતાવે છે તે જ પુરસ્કાર વાપરે છે.",
  "training.lessons.staff-your-rewards.step3": "તે વાપરવા માટે, જ્યારે તમે ખરીદો ત્યારે કોડ બતાવો. ટિલ પરની વ્યક્તિ તે ટાઇપ કરે છે અને તેને વપરાયેલો ચિહ્નિત કરે છે — દરેક કોડ બરાબર એક વાર કામ કરે છે.",
  "training.lessons.staff-your-rewards.step4": "પુરસ્કાર Business-પ્લાનની મજા છે. જો તમારો સ્ટોર Business પર નથી, તો Rewards ટેબ તેના બદલે લૉક કરેલો દરવાજો બતાવે છે — તે પ્લાન છે, ભૂલ નથી.",
  "training.lessons.staff-your-rewards.title": "તમારા પુરસ્કાર: તમારો કોડ શોધવો અને તે વાપરવો",
