  "pos.shopify.connectedToast": "Shopify જોડાયું. તેનું વેચાણ હવે અહીં ગણાય છે.",
  "pos.shopify.domainPlaceholder": "your-store.myshopify.com",
  "pos.shopify.help": "Shopify POS વેચાણ એ Shopify ઓર્ડર છે. આ સ્ટોર જોડો અને દરેક ઓર્ડર તેની આઇટમ અહીં આપોઆપ સ્ટોકમાંથી બહાર કાઢે છે.",
  "pos.shopify.tokenNote": "ટોકન તમારા Shopify એડમિનમાં કસ્ટમ એપમાંથી આવે છે. તે ફક્ત સર્વર પર સંગ્રહાય છે અને ક્યારેય પાછું બતાવાતું નથી.",
